// TestTimerStub checks the methods, the constructors and the options of
// the double TimerStub.
func TestTimerStub(t *testing.T) {
	t.Parallel()

	t.Run("C", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "C", timerStubCSubject)

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			var seen []clocktest.TimerCCall
			s.OnC.OnRecord(func(c clocktest.TimerCCall) { seen = append(seen, c) })
			_ = timerStubC(t, s)
			_ = timerStubC(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of C")
		})
	})

	t.Run("Reset", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Reset", timerStubResetSubject)

		t.Run("records the arguments of the call", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			_ = timerStubReset(t, s)
			got := s.OnReset.AssertCalledOnce(t, "Reset records the call")
			a0 := timerStubResetArgs(t)
			assert.Equal(t, got.D, a0, "the call records D")
		})

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			var seen []clocktest.TimerResetCall
			s.OnReset.OnRecord(func(c clocktest.TimerResetCall) { seen = append(seen, c) })
			_ = timerStubReset(t, s)
			_ = timerStubReset(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of Reset")
		})
	})

	t.Run("Stop", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Stop", timerStubStopSubject)

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			var seen []clocktest.TimerStopCall
			s.OnStop.OnRecord(func(c clocktest.TimerStopCall) { seen = append(seen, c) })
			_ = timerStubStop(t, s)
			_ = timerStubStop(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of Stop")
		})
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()
		stub.ResetBehaviour(t, func(tb assert.TB) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb))
		})

		t.Run("clears the recorded calls of C", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			_ = timerStubC(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnC.CallCount(), 0, "ResetCalls clears the calls of C")
		})

		t.Run("keeps the results of Returns of C", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			want0 := timerStubCPins()
			s.OnC.Returns(want0)
			s.ResetCalls()
			got0 := timerStubC(t, s)
			assert.Equal(t, got0, want0, "ResetCalls keeps the Result of C")
		})

		t.Run("clears the recorded calls of Reset", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			_ = timerStubReset(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnReset.CallCount(), 0, "ResetCalls clears the calls of Reset")
		})

		t.Run("keeps the results of Returns of Reset", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			want0 := timerStubResetPins()
			s.OnReset.Returns(want0)
			s.ResetCalls()
			got0 := timerStubReset(t, s)
			assert.Equal(t, got0, want0, "ResetCalls keeps the Result of Reset")
		})

		t.Run("clears the recorded calls of Stop", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			_ = timerStubStop(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnStop.CallCount(), 0, "ResetCalls clears the calls of Stop")
		})

		t.Run("keeps the results of Returns of Stop", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			want0 := timerStubStopPins()
			s.OnStop.Returns(want0)
			s.ResetCalls()
			got0 := timerStubStop(t, s)
			assert.Equal(t, got0, want0, "ResetCalls keeps the Result of Stop")
		})
	})

	t.Run("NewTimerStubDelayed", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStubDelayed(tb, d, clk))
		})
	})

	t.Run("TimerStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb, clocktest.TimerStubStrict()))
		})
	})

	t.Run("TimerStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes C to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := clocktest.NewTimerStub(t)
			s := clocktest.NewTimerStub(t, clocktest.TimerStubDelegateTo(inner))
			_ = timerStubC(t, s)
			inner.OnC.AssertCalledOnce(t, "C calls the implementation")
		})

		t.Run("passes Reset to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := clocktest.NewTimerStub(t)
			s := clocktest.NewTimerStub(t, clocktest.TimerStubDelegateTo(inner))
			_ = timerStubReset(t, s)
			inner.OnReset.AssertCalledOnce(t, "Reset calls the implementation")
		})

		t.Run("passes Stop to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := clocktest.NewTimerStub(t)
			s := clocktest.NewTimerStub(t, clocktest.TimerStubDelegateTo(inner))
			_ = timerStubStop(t, s)
			inner.OnStop.AssertCalledOnce(t, "Stop calls the implementation")
		})
	})

	t.Run("TimerStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb, clocktest.TimerStubWithClock(clk)))
		})
	})

	t.Run("TimerStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb, clocktest.TimerStubWithRandSource(src)))
		})
	})

	t.Run("TimerStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb, clocktest.TimerStubBenchMode()))
		})
	})

	t.Run("TimerStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) timerStubInstance {
			return timerStubInstanceOf(
				tb,
				clocktest.NewTimerStub(tb, clocktest.TimerStubWithClock(clk), clocktest.TimerStubWithLatency(d)),
			)
		})
	})

	t.Run("WithTimerC", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of C", func(t *testing.T) {
			t.Parallel()
			called := false
			s := clocktest.NewTimerStub(t, clocktest.WithTimerC(func() <-chan time.Time {
				called = true
				var z0 <-chan time.Time
				return z0
			}))
			_ = timerStubC(t, s)
			assert.True(t, called, "WithTimerC sets the function of C")
		})
	})

	t.Run("WithTimerReset", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Reset", func(t *testing.T) {
			t.Parallel()
			called := false
			s := clocktest.NewTimerStub(t, clocktest.WithTimerReset(func(_ time.Duration) bool {
				called = true
				var z0 bool
				return z0
			}))
			_ = timerStubReset(t, s)
			assert.True(t, called, "WithTimerReset sets the function of Reset")
		})
	})

	t.Run("WithTimerStop", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Stop", func(t *testing.T) {
			t.Parallel()
			called := false
			s := clocktest.NewTimerStub(t, clocktest.WithTimerStop(func() bool {
				called = true
				var z0 bool
				return z0
			}))
			_ = timerStubStop(t, s)
			assert.True(t, called, "WithTimerStop sets the function of Stop")
		})
	})
}

// TestTimerCStub checks the methods of TimerCStub, which configures C.
func TestTimerCStub(t *testing.T) {
	t.Parallel()

	t.Run("Returns", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the results of each call of C", func(t *testing.T) {
			t.Parallel()
			s := clocktest.NewTimerStub(t)
			want0 := timerStubCPins()
			s.OnC.Returns(want0)
			got0 := timerStubC(t, s)
			assert.Equal(t, got0, want0, "C returns the Result that Returns sets")
		})

		t.Run("configures C for strict mode", func(t *testing.T) {
			t.Parallel()
			r := assert.NewRecorder()
			s := clocktest.NewTimerStub(r)
			s.OnC.Strict()
			var want0 <-chan time.Time
			s.OnC.Returns(want0)
			_ = timerStubC(t, s)
			assert.False(t, r.Failed(), "strict mode accepts the call of C")
		})
	})
}

